// Verify the exact Webhook raw-body bytes. Enable NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers ?? {};
const timestamp = String(headers['x-telescreen-timestamp'] ?? '');
const nonce = String(headers['x-telescreen-nonce'] ?? '');
const signature = String(headers['x-telescreen-signature'] ?? '');
const rawBodyBase64 = item.binary?.data?.data;
const timestampSeconds = Number(timestamp);
const nowSeconds = Math.floor(Date.now() / 1000);
const secret = $env.TELESCREEN_POLICE_SIGNING_SECRET;
const globalData = $getWorkflowStaticData('global');
const nonceStore = globalData.policePushNonces ?? {};
for (const [savedNonce, expiresAt] of Object.entries(nonceStore)) {
  if (typeof expiresAt !== 'number' || expiresAt <= nowSeconds) delete nonceStore[savedNonce];
}
let valid = false;
if (typeof secret === 'string' && secret.length > 0 && /^[0-9]+$/.test(timestamp) && Number.isSafeInteger(timestampSeconds) && /^[0-9a-f]{32}$/i.test(nonce) && /^v1=[0-9a-f]{64}$/.test(signature) && typeof rawBodyBase64 === 'string' && Math.abs(nowSeconds - timestampSeconds) <= 300 && !Object.prototype.hasOwnProperty.call(nonceStore, nonce)) {
  const rawBody = Buffer.from(rawBodyBase64, 'base64');
  const prefix = Buffer.from(`${timestamp}.${nonce}.`, 'utf8');
  const digest = crypto.createHmac('sha256', Buffer.from(secret, 'utf8')).update(prefix).update(rawBody).digest('hex');
  const expected = Buffer.from(`v1=${digest}`, 'utf8');
  const provided = Buffer.from(signature, 'utf8');
  if (expected.length === provided.length && crypto.timingSafeEqual(expected, provided)) {
    nonceStore[nonce] = nowSeconds + 600;
    valid = true;
  }
}
globalData.policePushNonces = nonceStore;
return [{ json: { ...item.json, valid }, ...(item.binary ? { binary: item.binary } : {}) }];

// Replace this safe placeholder with local scan logic. Never return task input values.
const crypto = require('crypto');
const task = $json.body;
const callback = task.callback;
const result = { contract_version: task.contract_version, task_id: task.task_id, status: 'completed', summary: 'Example placeholder: replace with local Police verification logic', findings: [], result_token: callback.result_token };
if (task.task_type === 'verify_remediation') result.outcome = 'failed';
if (task.task_type === 'scan_shard') {
  result.stats = { resources_scanned: 0, resources_failed: 0, bytes_scanned: 0 };
  result.complete_locators = [];
}
const resultBody = JSON.stringify(result);
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomBytes(16).toString('hex');
return [{ json: { callbackUrl: callback.url, resultBody, timestamp, nonce, signingInput: `${timestamp}.${nonce}.${resultBody}` } }];
